graphql.query:
# number literals were redacted to 0: write the real ones (or variables) back
query listFtpdServiceUserProducts($customerId: ID!, $filters: [String!], $exposeTotalPrice: Boolean, $priceEstimationDate: DateTime) {
  listFtpdProducts(
    customerId: $customerId
    exposeTotalPrice: $exposeTotalPrice
    priceEstimationDate: $priceEstimationDate
  ) @limit(limit: 0) @filter(filters: $filters) {
    ...FtpdServiceUserProductParts
    __typename
  }
}

