  id
  status
  name
  marketId
  distributionChannelId
  productSerialNumber
  parentProductId
  eventGenerating
  rootProductId
  quoteId
  quantity
  sourceQuoteItemId
  startDate
  effectiveDate
  disconnectionReason
  disconnectionReasonDescription
  terminationDate
  extendedParameters
  technicalBarringRecord {
    id
    barringType
    businessBarringRecordId
    __typename
  }
  productFamily {
    id
    __typename
  }
  businessBarringSpecification {
    id
    name
    extendedParameters
    __typename
  }
  businessBarringRecord {
    id
    businessBarringSpecification {
      id
      name
      __typename
    }
    __typename
  }
  numberOfInstallments
  expirationDate
  originalExpirationDate
  isOneTimeOffering
  place {
    id
    name
    origin {
      address {
        country
        streetName
        streetNr
        streetNrSuffix
        stateOrProvince
        postCode
        city
        extendedAttributes
        __typename
      }
      __typename
    }
    __typename
  }
  billingAccount {
    id
    __typename
  }
  characteristic {
    id
    name
    value
    attributeId
    businessType
    technical
    __typename
  }
  productOffering {
    id
    name
    origin {
      ...FtpdProductOfferingParts
      __typename
    }
    __typename
  }
  productPrice {
    priceType
    rateCurrency
    priceCurrency
    priceAlteration {
      priceAlterationType
      priceType
      name
      promotionId
      extendedParameters
      validFor {
        startDateTime
        endDateTime
        __typename
      }
      price {
        percentage
        __typename
      }
      __typename
    }
    price {
      pricePlanId
      overridden
      valueSubTotalPriceIncludingTaxRounded
      valueBasePriceIncludingTaxRounded
      valueIncludingTaxRounded
      approxInstallmentPaymentAmountIncludingTaxRounded
      downPaymentValueIncludingTaxRounded
      __typename
    }
    __typename
  }
  businessGroup {
    id
    name
    extendedParameters
    marketingBundleId
    __typename
  }
  relatedParty {
    id
    role
    atReferredType
    userOfService
    name
    validFor {
      startDateTime
      endDateTime
      __typename
    }
    origin {
      ... on Individual {
        contactMedium {
          characteristic {
            emailAddress
            __typename
          }
          type
          mediumType
          preferred
          __typename
        }
        familyName
        fullName
        givenName
        __typename
      }
      ... on Customer {
        name
        engagedParty {
          id
          origin {
            ... on Individual {
              extendedAttributes
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  realizingService {
    id
    name
    role
    __typename
  }
  productRelationship {
    relationshipType
    product {
      id
      name
      __typename
    }
    __typename
  }
  customerCategory {
    id
    name
    __typename
  }
  __typename
}

